        "soru": "Kedilerde zigomatik tükürük bezinin yangısında (sialadenitis) karşılaşılan karakteristik klinik belirtileri ve anatomik nedenini açıklayınız.",
        "ideal_cevap": "Zigomatik tükürük bezi anatomik olarak orbita tabanına ve retrobulbar alana çok yakın yerleştiğinden yangılanması durumunda göz küresine baskı yapar; bu nedenle hastalarda Şaşılık (Strabismus) ve perioküler şişkinlik görülür. Ayrıca çiğneme kaslarının ve mandibulanın hareketinde şiddetli ağrı oluşturduğu için hayvanda ağzı açmaya karşı belirgin isteksizlik şekillenir.",
