        "ideal_cevap": "Hipokalemik acil koma olguları haricinde intravenöz potasyum (K+) uygulama hızı kesinlikle 0.5 mEq/kg/saat değerini geçmemelidir. Hızlı verilen potasyum miyokardiyal iletiyi bozarak ölümcül ventriküler fibrilasyon veya kardiyak arreste neden olur. Bu nedenle potasyum infüzyonu alan riskli hastalarda sürekli Elektrokardiyogram (EKG) monitörizasyonu zorunludur.",
