        "ideal_cevap": "Hastalığın birincil etkeni olarak Clostridium türü bakteriler (özellikle Clostridium perfringens enterotoksinleri) sorumlu tutulmaktadır. Genellikle küçük ırk köpekleri (Minyatür Pinscher, Yorkshire Terrier vb.) etkiler. Tanısal açıdan en karakteristik laboratuvar bulgusu; plazma protein konsantrasyonu normal veya normale yakın sınırlardayken, şiddetli sıvı kaybına bağlı olarak hematokritin (PCV) aşırı yükselerek %55'in üzerine çıkmasıdır (belirgin hemokonsantrasyon).",
