        "ideal_cevap": "GDV'li hastaların yaklaşık %40'ında aritmi saptanır ve bu aritmiler genellikle postoperatif 12-36. saatler arasında başlar. En sık Prematüre Ventriküler Kontraksiyonlar (PVC), paroksismal ventriküler taşikardi ve multifokal ventriküler taşiaritmiler görülür. Kalp atımı >160/dk ve nabız zayıfsa tedavi gerekir; ilk tercih IV Lidokaindir (2 mg/kg yavaş bolus, 8 mg/kg'a kadar çıkılabilir). Yanıtsız olgularda Prokainamid uygulanır. Tedavi öncesi hipokalemi ve metabolik asidoz mutlaka düzeltilmelidir.",
