        "ideal_cevap": "Gastrik leiomyosarkom, mide duvarındaki düz kas hücrelerinden köken alan ve oldukça yavaş büyüyen malign bir neoplazidir. Bu tümör hücreleri otonom olarak kontrolsüz İnsülin-benzeri Büyüme Faktörü (Insulin-like Growth Factor - IGF) üretir ve salgılar. IGF kanda insülin reseptörlerini uyararak glukozun hızla hücre içine girmesine ve derin paraneoplastik hipoglisemiye yol açar; bu hipoglisemi sonucunda hastalarda epileptik nöbetler (seizure/konvülsiyon) şekillenir.",
