        "ideal_cevap": "PKE'de bağırsak mukozasındaki vasküler ve epitelyal geçirgenlik artışı sonucu plazma albümini ile benzer moleküler ağırlığa sahip olan doğal antikoagülan madde 'Antitrombin-III (AT-III)' lümene kaybedilir. AT-III'ün tükenmesi pıhtılaşma kaskadını kontrolsüz aktive ederek hiperkoagülasyona ve sistemik tromboza neden olur. Profilaksi amacıyla: Düşük doz Aspirin (köpeklerde 0.5 mg/kg/gün PO) ve unfraksiyone/DDA Heparin (200-250 IU/kg SC günde 3 defa) uygulanır.",
