        "ideal_cevap": "Fekal Alfa-1 Proteinaz İnhibitörü (α1-PI) ölçümüdür. Alfa-1 proteinaz inhibitörü karaciğerde sentezlenir, albümin büyüklüğündedir, bağırsaktan aktif salgılanmaz ve emilmez; en önemlisi antiproteolitik aktivitesi olduğu için bağırsak bakterileri veya enzimleri tarafından sindirilmeden (hidrolize olmadan) feçeste değişmeden atılır. Uygulama: İntrarektal herhangi bir lavman veya manipülasyon yapılmaksızın, üst üste 3 gün boyunca toplanan taze feçes örneklerinde ölçüm gerçekleştirilir.",
