        "soru": "Preanestezik ilaçların kullanılmasındaki temel amaçları maddeler halinde açıklayınız.",
        "ideal_cevap": "1. Sedasyon sağlamak (ağrı, huysuzluk, korku ve endişeyi yatıştırmak).\n2. Anesteziye girişi kolaylaştırmak (eksitasyonsuz indüksiyon ve sakin uyanma temin etmek).\n3. Genel anesteziklerin yan etkilerini elimine etmek (örn: ketaminin aşırı salivasyonunu veya halotanın bradikardi/aritmisini atropinle önlemek).\n4. Anestezi oluşturmak için gerekli genel anestezik madde miktarını azaltmak (hızlı indüksiyon ve erken uyanma sağlamak).",
