        "ideal_cevap": "1. Kalp frekansı yüksek olan hastalarda (köpeklerde dakikada 140'ın üzeri, kedilerde dakikada 160'ın üzeri).\n2. Kongestif kalp yetmezliği hastalarında.\n3. Konstipasyonlu (şiddetli kabızlık) ve ileuslu (bağırsak tıkanması/felci) hayvanlarda (çünkü atropin bağırsak peristaltiğini daha da azaltır).",
