        "soru": "Asepromazinin (Vetranquil) antiemetik, antidisritmik ve periferik vazodilatasyon etkilerini klinik önemiyle açıklayınız.",
        "ideal_cevap": "Antiemetik etki: Çok küçük dozlarda bile anestezi boyunca kusmayı önler, araba tutması vakalarında tercih edilir.\nAntidisritmik etki: Adrenalin ve halotanın oluşturabileceği tehlikeli ventriküler disritmileri antagonize eder.\nPeriferik vazodilatasyon: Damarları genişleterek ısı kaybı (hipotermi) ve hipotansiyona yol açar; bu nedenle şoktaki ve hipovolemik hastalarda kullanılmamalıdır.",
