        "ideal_cevap": "Ksilazin uygulandıktan sonra uykulu hal ve sedasyon 1-2 saat boyunca devam edebilir; ancak analjezik etkisi yalnızca 15-30 dakika kadar kısa sürelidir. Bu nedenle ksilazin sedasyonunda ağrılı cerrahi müdahaleler ilacın etkisinin görülmesinden itibaren ilk 10-15 dakika içinde tamamlanmalıdır.",
