        "ideal_cevap": "Solunum: Hem solunum sayısını hem de tidal volümü azaltarak solunum depresyonu yaparlar (ventilatör desteği gerekir).\nBağırsak motilitesi: Erken dönemde peristaltiği artırarak kusma ve defekasyona, uzun dönemde ise peristaltiği azaltarak konstipasyona yol açarlar.\nPupilla: Köpeklerde pupillada daralma (miyozis), kedilerde ise pupillada genişleme (midriyazis) oluştururlar.",
