    "ozet": "Bu eğitim modülü; veteriner hekimlikte anestezi ve ilişkili temel tıbbi terimleri, anesteziklerin farmakokinetik ve etki mekanizmalarını, türe ve metabolizmaya bağlı biyolojik farklılıkları, operasyon öncesi preanestezik hasta muayenesini, ASA risk sınıflandırmasını, laboratuvar ve kan gazı analizlerinin anestezi protokollerine etkisini, cerrahi hasta hazırlığını, olası perioperatif komplikasyonları ve intraoperatif sıvı sağaltımı ilkelerini kapsamaktadır.",
