      "Asidozda (böbrek yetmezliği, şok, üretral obstrüksiyon) barbitüratların etkinliği artar, bu nedenle doz belirgin şekilde azaltılmalıdır.",
      "Arteriyel PaCO2 normal değeri 35-45 mmHg olup, 45 üzeri solunum depresyonunu, 60 üzeri ise kritik ventilasyon yetersizliğini belgeler.",
      "Arteriyel PaO2 80-110 mmHg normal kabul edilir; 80 altı hipoksi, 60 altı acil oksijen desteği zorunluluğudur.",
