        "ideal_cevap": "Yağ dokusu zengin obez hayvanlarda kanlanma oranı düşüktür; bu nedenle doz mutlak vücut ağırlığına göre değil ideal yağsız ağırlığa göre hesaplanır ve bu hayvanlar daha az anestezik maddeye gereksinim duyar. Aşırı zayıf ve kaşektik hayvanlar ise hipoproteinemi ve karaciğer yetmezliği riski taşır, anesteziklere aşırı duyarlıdır, hipotermiye çok hızlı girerler ve anesteziden uyanmaları gecikir.",
