        "ideal_cevap": "Enjektabl anestezikler vücuda (iv, im vb.) verildikten sonra hızla organlara dağılır ve etki süreleri tamamen ilacın redistribüsyonuna, karaciğer biyotransformasyonuna ve böbrek atılımına bağlıdır; bu eliminasyon süreçlerine dışarıdan anlık müdahale edilemez. İnhalasyon anesteziklerinde ise anestezik gaz ventilasyon yoluyla her nefes alıp vermede doğrudan akciğerlerden atılabilir ve derinlik saniyeler içinde değiştirilebilir.",
