        "ideal_cevap": "Böbrek yetersizliği, üretral obstrüksiyon ve şok gibi tablolarda kan pH'sı aside kayar (asidoz). Barbitüratlar zayıf asit karakterli ilaçlar olduklarından, asidik ortamda iyonize olmamış (lipofilik) fraksiyonları artar ve kan-beyin bariyerini çok daha yoğun aşarlar; bu nedenle barbitüratın santral etkisi şiddetlenir ve standart doza kıyasla mutlaka çok daha az miktarda barbitürat verilmelidir.",
