        "ideal_cevap": "PaCO2 normalde 35-45 mmHg'dir; 45 mmHg üzeri solunum depresyonunu, 60 mmHg üzeri ise acil mekanik ventilasyon gerektiren ciddi solunum yetmezliğini belgeler. PaO2 normalde 80-110 mmHg arasındadır; 80 mmHg altı doku hipoksisini, 60 mmHg altı ise acil oksijen takviyesi gerektiren kritik hipoksemiyi gösterir.",
